import random

def ticked(times):
    clock = LamportClock()
    for _ in range(times):
        clock.tick()
    return clock

def simulate(seed, steps=300):
    """Random ticks, sends and deliveries among 3 processes; returns "ok" or a description of the first rule broken."""
    rng = random.Random(seed)
    clocks = [LamportClock() for _ in range(3)]
    last = [0, 0, 0]
    in_flight = []                         # (timestamp, destination)
    for step in range(steps):
        p = rng.randrange(3)
        action = rng.choice(["tick", "send", "receive"])
        if action == "receive" and not in_flight:
            action = "tick"
        if action == "tick":
            now = clocks[p].tick()
        elif action == "send":
            now = clocks[p].send()
            in_flight.append((now, rng.choice([q for q in range(3) if q != p])))
        else:
            stamp, p = in_flight.pop(rng.randrange(len(in_flight)))
            now = clocks[p].receive(stamp)
            if now <= stamp:
                return f"step {step}: process {p} received a message stamped {stamp} and its time became {now}, which is not later"
        if now <= last[p]:
            return f"step {step}: process {p} went from {last[p]} to {now}; its time must grow with every event"
        if clocks[p].time != now:
            return f"step {step}: process {p} returned {now} but its time attribute is {clocks[p].time}"
        last[p] = now
    return "ok"

