class LamportClock:
    def __init__(self):
        self.time = 0

    def tick(self):
        self.time += 1
        return self.time

    def send(self):
        # Sending is an event: the stamp is the time after the increment.
        return self.tick()

    def receive(self, timestamp):
        # Land after both our own history and the sender's.
        self.time = max(self.time, timestamp) + 1
        return self.time
